module logic;
use model {Change,Edit};
use util {reverse};
fn run(text:Text,start:I64,count:I64,replacement:Text)->Edit<Change> {
 let length=Text::length(text);
 if start<0 || start>length {Err(1)} else {
  if count<0 || count>length-start {Err(2)} else {
   let suffix_start=start+count;
   let removed=Text::slice(text,start,count);
   let merged=Text::concat(Text::concat(Text::slice(text,0,start),replacement),Text::slice(text,suffix_start,length-suffix_start));
   Ok(Change {text:merged,removed:removed,scalar_delta:Text::length(replacement)-count,byte_delta:Bytes::length(Text::bytes(merged))-Bytes::length(Text::bytes(text))})
  }
 }
}

